// Test reading directory entries
TEST_F(DirectoryApiTest, ReadDirEntries) {
    DirStream *stream = nullptr;
    ASSERT_EQ(file_opendir(test_dir.c_str(), &stream), kOk);
    ASSERT_NE(stream, nullptr);

    std::vector<std::string> found_entries;
    std::vector<FileType> found_types;

    DirEntry *entry;
    MmResult result;
    while ((result = file_readdir(stream, &entry)) == kOk && entry != nullptr) {
        found_entries.push_back(entry->name);
        found_types.push_back(entry->type);
    }

    EXPECT_EQ(result, kOk); // Should end with kOk when reaching EOF

    // Verify we found expected entries (. and .. are typically included)
    EXPECT_THAT(found_entries, ::testing::Contains("."));
    EXPECT_THAT(found_entries, ::testing::Contains(".."));
    EXPECT_THAT(found_entries, ::testing::Contains("file1.txt"));
    EXPECT_THAT(found_entries, ::testing::Contains("file2.txt"));
    EXPECT_THAT(found_entries, ::testing::Contains("subdir"));

    // Check that we have reasonable entry types
    EXPECT_THAT(found_types, ::testing::Contains(kFileTypeDirectory));
    EXPECT_THAT(found_types, ::testing::Contains(kFileTypeRegularFile));

    file_closedir(stream);
}

