// Test multiple concurrent directory streams
TEST_F(DirectoryApiTest, MultipleConcurrentStreams) {
    // Create a second test directory
    auto test_dir2 = std::filesystem::temp_directory_path() / "dir_api_test2";
    std::filesystem::create_directories(test_dir2);
    std::ofstream(test_dir2 / "other_file.txt") << "content";

    DirStream *stream1 = nullptr;
    DirStream *stream2 = nullptr;

    // Open both directories
    ASSERT_EQ(file_opendir(test_dir.c_str(), &stream1), kOk);
    ASSERT_EQ(file_opendir(test_dir2.c_str(), &stream2), kOk);
    ASSERT_NE(stream1, nullptr);
    ASSERT_NE(stream2, nullptr);
    ASSERT_NE(stream1, stream2); // Should be different objects

    // Read from both streams alternately
    DirEntry *entry1, *entry2;
    std::vector<std::string> entries1, entries2;

    // Read first entry from each
    if (file_readdir(stream1, &entry1) == kOk && entry1) {
        entries1.push_back(entry1->name);
    }
    if (file_readdir(stream2, &entry2) == kOk && entry2) {
        entries2.push_back(entry2->name);
    }

    // The streams should be independent
    EXPECT_NE(entries1.empty() || entries2.empty(), true);

    file_closedir(stream1);
    file_closedir(stream2);

    // Cleanup
    std::filesystem::remove_all(test_dir2);
}

// Test entry type detection
TEST_F(DirectoryApiTest, EntryTypeDetection) {
    DirStream *stream = nullptr;
    ASSERT_EQ(file_opendir(test_dir.c_str(), &stream), kOk);

    std::unordered_map<std::string, FileType> entry_types;

    DirEntry *entry;
    while (file_readdir(stream, &entry) == kOk && entry != nullptr) {
        entry_types[entry->name] = entry->type;
    }

    // Check specific entry types
    if (entry_types.count("file1.txt")) {
        EXPECT_EQ(entry_types["file1.txt"], kFileTypeRegularFile);
    }
    if (entry_types.count("subdir")) {
        EXPECT_EQ(entry_types["subdir"], kFileTypeDirectory);
    }
    if (entry_types.count("link_to_file1")) {
        EXPECT_EQ(entry_types["link_to_file1"], kFileTypeSymbolicLink);
    }

    file_closedir(stream);
}

