// Performance/stress test
TEST_F(DirectoryApiTest, StressTestManyFiles) {
    // Create many files for stress testing
    const int num_files = 100;
    auto stress_dir = std::filesystem::temp_directory_path() / "stress_test";
    std::filesystem::create_directories(stress_dir);

    // Create many files
    for (int i = 0; i < num_files; ++i) {
        std::string filename = "file_" + std::to_string(i) + ".txt";
        std::ofstream(stress_dir / filename) << "content " << i;
    }

    DirStream *stream = nullptr;
    ASSERT_EQ(file_opendir(stress_dir.c_str(), &stream), kOk);

    int count = 0;
    DirEntry *entry;
    while (file_readdir(stream, &entry) == kOk && entry != nullptr) {
        count++;
        // Verify name is not empty and type is reasonable
        EXPECT_GT(strlen(entry->name), 0);
        EXPECT_NE(entry->type, kFileTypeUnknown);
    }

    // Should have found at least the files we created plus . and ..
    EXPECT_GE(count, num_files + 2);

    file_closedir(stream);
    std::filesystem::remove_all(stress_dir);
}

